package com.tce.smart.platform.service.print;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.tce.smart.platform.core.entity.print.PrintTemplateVersion;
import com.tce.smart.platform.core.mapper.PrintTemplateMapper;
import org.springframework.stereotype.Component;
import java.util.*;
import static com.tce.smart.platform.service.print.PrintJobTransactions.*;
/** 只接受人员标识，可信来源资料及实际选择在创建时完整冻结。 */
@Component public class PrintJobPreparation {
 final PrintSubjectSource subjects;final PrintTemplateResolver resolver;final PrintTemplateMapper templates;final PrintRendererClient renderer;
 public PrintJobPreparation(PrintSubjectSource subjects,PrintTemplateResolver resolver,PrintTemplateMapper templates,PrintRendererClient renderer){this.subjects=subjects;this.resolver=resolver;this.templates=templates;this.renderer=renderer;}
 public ObjectNode freeze(ObjectNode request,String id,JsonNode printer,boolean preview){String park=printer.path("parkId").asText(),type=request.path("subjectType").asText(),subjectId=request.path("subjectId").asText();if(!Arrays.asList("STAFF","SUPPLIER_PERSON","VISITOR","VISITOR_COMPANION","ADMITTANCE","ADMITTANCE_COMPANION").contains(type)||subjectId.isEmpty()||subjectId.length()>128)throw error(422,"INVALID_REQUEST");ObjectNode subject=subjects.load(park,type,subjectId);if(subject==null)throw error(404,"PRINT_SUBJECT_NOT_FOUND");for(String k:Arrays.asList("parkId","subjectType","subjectId")){String expected="parkId".equals(k)?park:request.path(k).asText();if(!expected.equals(subject.path(k).asText()))throw error(403,"PRINT_SCOPE_DENIED");}for(String k:Arrays.asList("printItemType","personType","classificationCode"))if(request.hasNonNull(k)&&!request.path(k).equals(subject.path(k)))throw error(422,"PRINT_SUBJECT_CLASSIFICATION_MISMATCH");if("STAFF_CARD".equals(subject.path("printItemType").asText())&&(!subject.path("cardRegistrationVerified").asBoolean()||subject.at("/fields/cardNo").asText().trim().isEmpty()))throw error(422,"PRINT_CARD_REGISTRATION_REQUIRED");String mode=request.path("printMode").asText(printer.path("defaultPrintMode").asText());PrintPrinterService.requireMode(printer,mode,subject.path("printItemType").asText());JsonNode selection=request.path("selection").deepCopy();if(!selection.isObject())throw error(422,"INVALID_REQUEST");if(preview&&Arrays.asList("PAIR","EXPLICIT").contains(selection.path("kind").asText()))((ObjectNode)selection).put("manualSelectionConfirmed",true);ObjectNode resolution=resolver.select(park,subject,selection);List<PrintTemplateVersion> versions=new ArrayList<>();for(String key:Arrays.asList("frontTemplateVersionId","backTemplateVersionId"))if(resolution.hasNonNull(key)){PrintTemplateVersion version=templates.findTemplateVersion(resolution.path(key).asText());if(version==null||!park.equals(version.getParkId()))throw error(403,"PRINT_SCOPE_DENIED");JsonNode page=PrintJson.read(version.getPageSpecJson());JsonNode media=printer.path("mediaSpec");if(media.hasNonNull("widthMm")&&Math.abs(media.path("widthMm").asDouble()-page.path("widthMm").asDouble())>0.05)throw error(422,"PRINTER_MEDIA_MISMATCH");if(media.hasNonNull("heightMm")&&Math.abs(media.path("heightMm").asDouble()-page.path("heightMm").asDouble())>0.05)throw error(422,"PRINTER_MEDIA_MISMATCH");if(media.hasNonNull("maxPrintableWidthMm")&&page.path("widthMm").asDouble()>media.path("maxPrintableWidthMm").asDouble()+0.05)throw error(422,"PRINTER_MEDIA_MISMATCH");versions.add(version);}ObjectNode frozen=subject.deepCopy();frozen.set("resolution",resolution);ObjectNode render=renderer.freezeJobRequest(id,mode,versions,subject);if(preview){render.remove("jobId");render.put("purpose","PREVIEW").put("previewId",id);resolution.remove(Arrays.asList("confirmedBy","confirmedAt"));resolution.put("manualSelectionConfirmed",false);}frozen.set("renderRequest",render);return frozen;}
}
